// 1. Single-block status & schema validation
pm.test("Status code is 201 & Response is JSON", function () {
    pm.response.to.have.status(201);
    pm.response.to.be.withBody;
    pm.response.to.be.json;
});

// 2. Safe parse & assertions
const res = pm.response.code === 201 ? pm.response.json() : null;

if (res) {
    pm.test("Response contains valid auth credentials", function () {
        pm.expect(res.access).to.be.a("string").and.not.empty;
        pm.expect(res.role).to.eql("user");

        // Dynamic match: matches {{username}} if set in environment/data file
        const expectedUser = pm.variables.get("username") || "alice";
        if (expectedUser && res.username) {
            pm.expect(res.username).to.eql(expectedUser);
        }
    });

    // 3. Store in Environment (one liner via optional chaining)
    res.access && pm.environment.set("user_token", res.access);
}

